import type { FreeCamera } from "@babylonjs/lite";
import { createBankedFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface ChaseCamera {
  camera: FreeCamera;
  bank(up: Vec): void;
}

const EPS = 1e-6;

function sub(a: Vec, b: Vec): Vec { return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z }; }
function scale(a: Vec, s: number): Vec { return { x: a.x * s, y: a.y * s, z: a.z * s }; }
function dot(a: Vec, b: Vec): number { return a.x*b.x + a.y*b.y + a.z*b.z; }
function length(a: Vec): number { return Math.sqrt(dot(a,a)); }
function normalize(a: Vec): Vec { const l = length(a); if (l < EPS) return {x:0,y:0,z:0}; return scale(a, 1/l); }
function perpendicularize(v: Vec, f: Vec): Vec { return sub(v, scale(f, dot(v, f))); }
function projectToPlane(v: Vec, f: Vec): Vec { const p = perpendicularize(v, f); const l = length(p); if (l < EPS) return {x:0,y:0,z:0}; return scale(p, 1/l); }

export function createChaseCamera(eye: Vec, target: Vec): ChaseCamera {
  const camera = createBankedFreeCamera(eye, target, { x: 0, y: 1, z: 0 });
  let prevUp: Vec = { x: 0, y: 1, z: 0 };

  const applyUp = (up: Vec) => {
    prevUp = up;
    camera.upVector.x = up.x;
    camera.upVector.y = up.y;
    camera.upVector.z = up.z;
  };

  // Initialize upright: project world up onto plane perpendicular to initial view direction.
  const f0 = normalize(sub(target, eye));
  const f0Len = length(f0);
  if (f0Len >= EPS) {
    const worldUp = { x: 0, y: 1, z: 0 };
    const init = projectToPlane(worldUp, f0);
    if (length(init) >= EPS) {
      applyUp(init);
    } else {
      // view direction is vertical; fall back to a stable perpendicular axis.
      const initFallback = projectToPlane({ x: 1, y: 0, z: 0 }, f0);
      applyUp(length(initFallback) >= EPS ? initFallback : { x: 0, y: 1, z: 0 });
    }
  } else {
    applyUp({ x: 0, y: 1, z: 0 });
  }

  const bank = (up: Vec): void => {
    const currentEye = { x: camera.position.x, y: camera.position.y, z: camera.position.z };
    const currentTarget = { x: camera.target.x, y: camera.target.y, z: camera.target.z };
    const f = normalize(sub(currentTarget, currentEye));
    const fLen = length(f);
    if (fLen < EPS) {
      return;
    }
    const u = normalize(up);
    const uLen = length(u);
    if (uLen < EPS) {
      return;
    }
    const desired = projectToPlane(u, f);
    if (length(desired) < EPS) {
      // Car up is parallel/anti-parallel to line of sight: keep previous roll.
      const kept = projectToPlane(prevUp, f);
      if (length(kept) >= EPS) {
        applyUp(kept);
      } else {
        // Previous roll is also undefined for this line of sight; choose a stable upright-ish axis.
        const worldUp = { x: 0, y: 1, z: 0 };
        const fallback = projectToPlane(worldUp, f);
        if (length(fallback) >= EPS) {
          applyUp(fallback);
        } else {
          const xUp = { x: 1, y: 0, z: 0 };
          const fallback2 = projectToPlane(xUp, f);
          if (length(fallback2) >= EPS) {
            applyUp(fallback2);
          } else {
            applyUp({ x: 0, y: 1, z: 0 });
          }
        }
      }
    } else {
      applyUp(desired);
    }
  };

  return { camera, bank };
}
```

